46	/**
47	 * 加密簽名
48	 */
49	export async function encryptSignature(
50	  publicKeyBase64: string,
51	  text: string,
52	): Promise<string> {
53	  const publicKeyPem = `-----BEGIN PUBLIC KEY-----\n${publicKeyBase64}\n-----END PUBLIC KEY-----`;
54	  const publicKey = forge.pki.publicKeyFromPem(publicKeyPem);
55	
56	  const encryptedBytes = publicKey.encrypt(text, "RSA-OAEP", {
57	    md: forge.md.sha256.create(),
58	  });
59	
60	  return forge.util.encode64(encryptedBytes);
61	}
