173	type SseStreamPayload = {
174	  delta?: string;
175	  source?: string;
176	  done?: boolean;
177	  error?: string;
178	};
179	
180	function isQuotaErrorText(status: number, text: string): boolean {
181	  return status === 429 || status === 503 || TRANSIENT_AI_ERROR_PATTERN.test(text);
182	}
183	
184	/** 把一行文字解析成 SSE payload；不是 `data: ` 開頭的行（例如空白分隔行）回傳 null */
185	function parseSseLine(rawLine: string): SseStreamPayload | null {
186	  const line = rawLine.trim();
187	  if (!line.startsWith("data: ")) return null;
188	  return JSON.parse(line.slice("data: ".length));
189	}
190	
191	/** 讀取一個 SSE response body，逐段解析出 payload 陣列（可能因為 chunk 邊界而一次拿到多個或零個） */
192	async function readSseChunk(
193	  reader: ReadableStreamDefaultReader<Uint8Array>,
194	  decoder: TextDecoder,
195	  bufferRef: { value: string },
196	): Promise<{ done: boolean; payloads: SseStreamPayload[] }> {
197	  const { done, value } = await reader.read();
198	  if (done) return { done: true, payloads: [] };
199	
200	  bufferRef.value += decoder.decode(value, { stream: true });
201	  const events = bufferRef.value.split("\n\n");
202	  bufferRef.value = events.pop() ?? ""; // 最後一段可能還不完整，留到下一輪繼續接
203	
204	  const payloads = events
205	    .map(parseSseLine)
206	    .filter((p): p is SseStreamPayload => p !== null);
207	  return { done: false, payloads };
208	}
209	
210	type StreamAccumulator = {
211	  content: string;
212	  source: string;
213	  hasReceivedContent: boolean;
214	};
215	
216	/** 套用單一 SSE payload 到累積狀態，並即時更新畫面上的訊息內容 */
217	function applyStreamPayload(
218	  payload: SseStreamPayload,
219	  acc: StreamAccumulator,
220	  context: AICallContext,
221	  mIdx: number,
222	  idx: number,
223	) {
224	  if (payload.error) throw new Error(payload.error);
225	
226	  if (payload.delta) {
227	    acc.content += payload.delta;
228	    acc.hasReceivedContent = true;
229	    context.messages.value[mIdx][idx] = {
230	      role: Role.Assistant,
231	      content: acc.content,
232	      timestamp: Date.now(),
233	      status: Status.Receiving,
234	    };
235	  }
236	
237	  if (payload.done) acc.source = payload.source ?? "";
238	}
239	
240	/** 讀完整個 SSE response body，過程中即時更新畫面，回傳最終累積狀態 */
241	async function consumeSseStream(
242	  res: Response,
243	  context: AICallContext,
244	  mIdx: number,
245	  idx: number,
246	): Promise<StreamAccumulator> {
247	  const reader = res.body!.getReader();
248	  const decoder = new TextDecoder("utf-8");
249	  const bufferRef = { value: "" };
250	  const acc: StreamAccumulator = { content: "", source: "", hasReceivedContent: false };
251	
252	  while (true) {
253	    const { done, payloads } = await readSseChunk(reader, decoder, bufferRef);
254	    if (done) break;
255	    for (const payload of payloads) {
256	      applyStreamPayload(payload, acc, context, mIdx, idx);
257	    }
258	  }
259	
260	  return acc;
261	}
262	
263	/**
264	 * 串流 AI 調用（flowId=6：Gemini File Search RAG；flowId=7／9：學習規劃探索助手；
265	 * flowId=8：未來教室設備支援助理）
266	 * 後端以 SSE 逐段吐出文字，格式為 `data: {delta, source, done, error}\n\n`
267	 */
268	async function callStream(
269	  context: AICallContext,
270	  mIdx: number,
271	  idx: number,
272	  config: CallConfig,
273	  signature: string,
274	) {
275	  context.messages.value[mIdx][idx] = {
276	    role: Role.Assistant,
277	    content: config.loadingText ?? "吉吉鳥正在尋找答案中",
278	    timestamp: Date.now(),
279	    status: Status.Pending,
280	  };
281	
282	  const res = await fetch(getApiUrl("/api/run?stream=true"), {
283	    method: "POST",
284	    headers: {
285	      "Content-Type": "application/json",
286	      Authorization: signature,
287	      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
288	    },
289	    body: JSON.stringify({
290	      input_value: config.content,
291	      ...(config.history ? { history: config.history } : {}),
292	      ...(config.image ? { image: config.image } : {}),
293	      ...(config.model ? { model: config.model } : {}),
294	    }),
295	  });
296	
297	  persistRenewedToken(res, context.jwtToken);
298	
299	  if (!res.ok || !res.body) {
300	    const errorText = await res.text();
301	    if (isQuotaErrorText(res.status, errorText)) {
302	      throw new QuotaExceededError(errorText);
303	    }
304	    throw new Error(errorText || `串流請求失敗 (${res.status})`);
305	  }
306	
307	  const { content, source, hasReceivedContent } = await consumeSseStream(
308	    res,
309	    context,
310	    mIdx,
311	    idx,
312	  );
313	
314	  context.messages.value[mIdx][idx] = {
315	    role: Role.Assistant,
316	    content: hasReceivedContent
317	      ? content
318	      : "目前找不到與這個問題相關的資料，請確認文件是否已上傳完成，或換個問法再試一次。",
319	    timestamp: Date.now(),
320	    status: Status.End,
321	    source,
322	  };
323	}
324	
325	/**
326	 * AI 調用主函數（包含錯誤處理和額度用光自動切換）
327	 */
328	export async function callAI(
329	  context: AICallContext,
330	  mIdx: number,
331	  idx: number,
332	  config: CallConfig,
333	  _stream: boolean = false,
334	) {
335	  try {
336	    await executeAICall(context, mIdx, idx, config);
337	  } catch (error) {
338	    // 如果是額度用光且當前是 flow 0，自動切換到 flow 1
339	    if (
340	      error instanceof QuotaExceededError &&
341	      config.flowId === "0" &&
342	      !context.route.query.flow
343	    ) {
344	      console.log("額度用光，自動切換到 flow 1");
345	      const fallbackConfig = { ...config, flowId: "1" };
346	      try {
347	        await executeAICall(context, mIdx, idx, fallbackConfig);
348	        return;
349	      } catch (fallbackError) {
350	        // flow 1 也失敗，顯示錯誤
351	        console.error(fallbackError);
352	        showErrorMessage(context.messages, mIdx, idx, fallbackError);
353	        return;
354	      }
355	    }
356	
357	    // 其他錯誤
358	    console.error(error);
359	    showErrorMessage(context.messages, mIdx, idx, error);
360	  }
361	}
