### 5.4 useAdvisingConversation.ts (第 129-162 行)

```typescript
async function send(userText: string): Promise<SendOutcome> {
  const current = exploration.value
  if (!current) throw new Error('exploration not loaded')

  sending.value = true
  streamingText.value = ''
  error.value = null

  try {
    const reply = await sendAdvisingMessage(current.id, userText, delta => {
      streamingText.value += delta
    })

    let patch: Partial<Exploration> = {}
    let isFinal = false

    const stage2 = parseStage2Reply(reply)
    if (stage2) {
      // Stage 2：10 題依序提問+反思
      patch.answers = applyStage2Reply(current, stage2, reply)
    } else if (isFinalReport(reply)) {
      // Stage 3：總結報告
      isFinal = true
      patch = { ...patch, ...applyFinalReport(current, reply) }
    } else if (!isFastAssessmentPrompt(reply) && (current.fast?.scores?.length ?? 0) > 0) {
      // Stage 1.5: FAST 自評後的回覆解析失敗時的保底機制
      const fallbackAnswers = buildFallbackAnswers(current, reply)
      if (fallbackAnswers) patch.answers = fallbackAnswers
    }

    exploration.value = { ...current, ...patch, updatedAt: new Date().toISOString() }
    await persistDerived(current, patch, { rethrow: isFinal })
    return { reply, isFinal }
  } catch (err) {
    error.value = err instanceof Error ? err.message : String(err)
    console.error('[useAdvisingConversation] send failed', err)
    throw err
  } finally {
    sending.value = false
  }
}
```

