// 5 張固定議題卡片 + 自訂議題輸入欄
async function start(topic: TopicKey, customLabel?: string) {
  if (busy.value) return
  const label = customLabel ?? t(TOPIC_CARDS.find(o => o.key === topic)?.labelKey ?? topic)
  creating.value = true
  try {
    // 1. 先建立探索紀錄（後端會預先把開場白寫進 history）
    const record = await createExploration({ topic, topicCustomLabel: customLabel })
    activeExploration.value = record
    creating.value = false
    // 2. 送出議題文字，等 AI 進入 Stage 1.5 FAST 自評才導向下一頁
    await send(label)
    router.push(`/fast/${record.id}`)  // 跳到 FastAssessmentPage
  } catch (err) {
    console.error('[TopicSelectPage] start failed', err)
    showToast(isQuotaError(err) ? t('common.quotaError') : t('topics.sendError'))
  } finally {
    creating.value = false
  }
}

const TOPIC_CARDS: TopicOption[] = [
  { key: 'academics', labelKey: 'topics.academics', descKey: 'topics.academicsDesc' },
  { key: 'course-selection', labelKey: 'topics.courseSelection', descKey: 'topics.courseSelectionDesc' },
