## 8. 認證機制比較

### 主聊天站 (src/lib/utils.ts)
```typescript
export function persistRenewedToken(res: Response, jwtToken: Ref<string>): void {
  const renewed = res.headers.get("X-Access-Token-Renewed");
  if (renewed) jwtToken.value = renewed;
}

// main.ts 中：
try {
  const jwtToken = localStorage.getItem(LocalStorageKey.JWT_TOKEN);
  if (!jwtToken) throw new Error("No JWT token found");
  const user = jwtDecode<JwtToken>(jwtToken);
  if (user?.iat && Math.floor(Date.now() / 1000) - user.iat > 8 * 60 * 60)
    throw new Error("Token expired");
  app.provide("user", user);
} catch (error) {
  localStorage.removeItem(LocalStorageKey.JWT_TOKEN);
  app.provide("user", null);
}
```

### explore app (apps/explore/src/services/auth.ts)
```typescript
export function readAuthToken(): string | null {
  try {
    return localStorage.getItem(STORAGE_KEYS.jwtToken);
  } catch {
    return null;
  }
}

export function persistRenewedToken(res: Response): void {
  const renewed = res.headers.get('X-Access-Token-Renewed');
  if (!renewed) return;
  try {
    localStorage.setItem(STORAGE_KEYS.jwtToken, renewed);
  } catch {
    // localStorage unavailable
  }
}
```

**兩者都用同一個 localStorage key（JWT_TOKEN），相容！**

